input.content:
.page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.subtitle {
  margin-bottom: 0.5rem;
}

.limitInfo {
  text-align: center;
  margin-bottom: 1rem;
}

.screen {
  width: 60%;
  text-align: center;
  padding: 0.5rem;
  margin-bottom: 1.5rem;
  background: #333;
  color: #fff;
  border-radius: 4px;
  letter-spacing: 0.3rem;
}

.auditorium {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 1.5rem;
}

.row {
  display: grid;
  grid-template-columns: 1.8rem repeat(4, 2.3rem) 4.6rem repeat(16, 2.3rem) 4.6rem repeat(4, 2.3rem) 1.8rem;
  align-items: center;
  gap: 0.2rem;
}

.rowLabel {
  text-align: center;
  font-size: 0.8rem;
  color: #555;
}

.seat {
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  font-size: 0.7rem;
  color: #fff;
  cursor: pointer;
  user-select: none;
}

.seat[data-state='unavailable'] {
  cursor: not-allowed;
}

.couch {
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 0.7rem;
  color: #fff;
  cursor: pointer;
  user-select: none;
}

.couch[data-state='unavailable'] {
  cursor: not-allowed;
}

.legend {
  display: flex;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.legendItem {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.swatch {
  width: 1rem;
  height: 1rem;
  border-radius: 3px;
  display: inline-block;
}

.selectedPanel {
  margin-bottom: 1.5rem;
  min-width: 300px;
}

.actions {
  display: flex;
  gap: 1rem;
}

