import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs, { Dayjs } from 'dayjs';
import { useCallback, useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { getMovies, getScreenings } from '../../api/client';
import { Movie, Screening } from '../../api/types';
import { resolveSelectedDate, todayISO, weekdayName } from '../../lib/dateFormat';

interface DayOption {
  iso: string;
  label: string;
}

function buildDayOptions(): DayOption[] {
  const options: DayOption[] = [];
  for (let i = 0; i < 5; i += 1) {
    const date = dayjs().add(i, 'day');
    options.push({ iso: date.format('YYYY-MM-DD'), label: i === 0 ? 'Today' : weekdayName(date) });
  }
  return options;
}

export function MovieList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const dayOptions = buildDayOptions();
  const selectedDate = resolveSelectedDate(searchParams.get('date'));

  const [movies, setMovies] = useState<Movie[]>([]);
  const [screenings, setScreenings] = useState<Screening[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  const load = useCallback(async (date: string) => {
    setLoading(true);
    setError(false);
    try {
      const [moviesResult, screeningsResult] = await Promise.all([getMovies(), getScreenings({ date })]);
      setMovies(moviesResult);
      setScreenings(screeningsResult);
    } catch {
      setError(true);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(selectedDate);
  }, [load, selectedDate]);

  function selectDate(iso: string) {
    setSearchParams({ date: iso });
  }

  const isPresetDate = dayOptions.some((option) => option.iso === selectedDate);

  const moviesForDay = movies
    .map((movie) => ({
      movie,
      screeningsToday: screenings
        .filter((screening) => screening.movieId === movie.id && screening.date === selectedDate)
        .sort((a, b) => a.time.localeCompare(b.time)),
    }))
    .filter((entry) => entry.screeningsToday.length > 0);

  return (
    <Box sx={{ maxWidth: 960, mx: 'auto', p: 4 }}>
      <Stack data-testid="day-picker" direction="row" spacing={1} alignItems="center" sx={{ mb: 4 }}>
        {dayOptions.map((option) => (
          <Button
            key={option.iso}
            data-testid="day-button"
            data-date={option.iso}
            data-selected={option.iso === selectedDate}
            variant={option.iso === selectedDate ? 'contained' : 'outlined'}
            onClick={() => selectDate(option.iso)}
          >
            {option.label}
          </Button>
        ))}
        <DatePicker
          value={isPresetDate ? null : dayjs(selectedDate, 'YYYY-MM-DD')}
          minDate={dayjs(todayISO(), 'YYYY-MM-DD')}
          onChange={(value: Dayjs | null) => {
            if (value && value.isValid()) selectDate(value.format('YYYY-MM-DD'));
          }}
          slotProps={{ textField: { 'data-testid': 'date-picker', size: 'small' } }}
        />
      </Stack>

      {loading && (
        <Typography data-testid="movies-loading">Loading…</Typography>
      )}

      {!loading && error && (
        <Box data-testid="movies-error">
          <Typography>Failed to load movies</Typography>
          <Button data-testid="movies-retry-button" onClick={() => load(selectedDate)}>
            Retry
          </Button>
        </Box>
      )}

      {!loading && !error && moviesForDay.length === 0 && (
        <Typography data-testid="movies-empty">No screenings on this day</Typography>
      )}

      {!loading && !error && moviesForDay.length > 0 && (
        <Stack data-testid="movie-list" spacing={2}>
          {moviesForDay.map(({ movie, screeningsToday }) => (
            <Card key={movie.id} data-testid="movie-card" data-movie-id={movie.id}>
              <CardContent>
                <Typography data-testid="movie-title" variant="h6">
                  {movie.title}
                </Typography>
                <Typography data-testid="movie-genre">{movie.genre}</Typography>
                <Typography data-testid="movie-runtime">{movie.runtimeMinutes} min</Typography>
                <Typography data-testid="movie-format">{movie.format}</Typography>
                <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
                  {screeningsToday.map((screening) => (
                    <Button
                      key={screening.id}
                      data-testid="screening-button"
                      data-screening-id={screening.id}
                      variant="outlined"
                      onClick={() => navigate(`/screenings/${screening.id}/seats`)}
                    >
                      {screening.time}
                    </Button>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          ))}
        </Stack>
      )}
    </Box>
  );
}

export default MovieList;

import Button from '@mui/material/Button';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { getMovie, getScreening } from '../../api/client';
import { Movie, Screening } from '../../api/types';
import { useBooking } from '../../booking/BookingContext';
import { formatPrice, seatLabel, toSummaryItems } from '../../lib/seats';

export function Summary() {
  const { id } = useParams<{ id: string }>();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { booking, removeItem } = useBooking();

  const [screening, setScreening] = useState<Screening | null>(null);
  const [movie, setMovie] = useState<Movie | null>(null);

  const bookingValid =
    !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;

  useEffect(() => {
    if (!bookingValid) {
      navigate('/', { replace: true });
      return;
    }
    let cancelled = false;
    getScreening(screeningId)
      .then(async (loadedScreening) => {
        const loadedMovie = await getMovie(loadedScreening.movieId);
        if (cancelled) return;
        setScreening(loadedScreening);
        setMovie(loadedMovie);
      })
      .catch(() => {
        if (!cancelled) navigate('/', { replace: true });
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screeningId, bookingValid]);

  if (!bookingValid || !screening || !movie || !booking) return null;

  const items = toSummaryItems(booking.seats);
  const total = items.reduce((sum, item) => sum + item.price, 0);
  const datetime = `${screening.date} ${screening.time}`;

  function onRemove(identifiers: string[]) {
    removeItem(identifiers);
    if (items.length <= 1) navigate(`/screenings/${screeningId}/seats`);
  }

  return (
    <div style={{ maxWidth: 800, margin: '0 auto', padding: '2rem' }}>
      <Typography data-testid="summary-title" variant="h4">
        Your tickets
      </Typography>

      <Stack data-testid="summary-list" spacing={2} sx={{ my: 2 }}>
        {items.map((item) => (
          <Stack
            key={item.identifiers.join('-')}
            data-testid="summary-item"
            direction="row"
            spacing={2}
            alignItems="center"
          >
            <Typography data-testid="summary-item-title">{movie.title}</Typography>
            <Typography data-testid="summary-item-datetime">{datetime}</Typography>
            <Typography data-testid="summary-item-row">{item.row}</Typography>
            <Typography data-testid="summary-item-seat">{seatLabel(item)}</Typography>
            <Typography data-testid="summary-item-price">{formatPrice(item.price)}</Typography>
            <Button data-testid="summary-item-remove-button" onClick={() => onRemove(item.identifiers)}>
              Remove
            </Button>
          </Stack>
        ))}
      </Stack>

      <Typography data-testid="summary-total" variant="h6">
        Total: {formatPrice(total)}
      </Typography>

      <Stack direction="row" spacing={2} sx={{ mt: 2 }}>
        <Button data-testid="back-button" variant="outlined" onClick={() => navigate(`/screenings/${screeningId}/seats`)}>
          Back
        </Button>
        <Button data-testid="confirm-button" variant="contained" onClick={() => navigate(`/screenings/${screeningId}/checkout`)}>
          Confirm
        </Button>
      </Stack>
    </div>
  );
}

export default Summary;

